"use strict";

/**
 * pg-http — a tiny, zero-dependency Postgres client for Neon, designed for
 * AWS Lambda where bundling the @neondatabase/serverless driver (or `pg`)
 * into asset-packaged functions is awkward.
 *
 * It speaks Neon's SQL-over-HTTP protocol with the global `fetch` (Node 18+):
 *   POST https://<api-host>/sql
 *   headers: Neon-Connection-String, Neon-Raw-Text-Output, Neon-Array-Mode
 *   body:    { query, params }
 *
 * The API host is derived from the connection string host by replacing the
 * first dot-segment with "api." — the same transform the official driver
 * uses (e.g. `ep-x-pooler.c-7.us-east-1.aws.neon.tech` →
 * `api.c-7.us-east-1.aws.neon.tech`).
 *
 * Values come back as raw text (Neon-Raw-Text-Output=true), so callers get
 * strings (or null). JSON/JSONB columns arrive as JSON strings — callers
 * JSON.parse them. Integers arrive as numeric strings — callers Number()
 * them when needed. This keeps the helper free of pg-types.
 *
 * This helper targets Neon specifically; it is used by the AWS control-plane
 * Lambdas, which only ever talk to the hosted Neon database.
 */

function endpointFromConnectionString(connectionString) {
  const u = new URL(connectionString);
  const apiHost = u.hostname.replace(/^[^.]+\./, "api.");
  return `https://${apiHost}/sql`;
}

function prepareParam(value) {
  if (value === undefined || value === null) return null;
  if (value instanceof Date) return value.toISOString();
  if (typeof value === "object") return JSON.stringify(value);
  return value;
}

async function pgQuery(connectionString, query, params = []) {
  if (!connectionString) throw new Error("DATABASE_URL is not configured");

  const res = await fetch(endpointFromConnectionString(connectionString), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
      "Neon-Connection-String": connectionString,
      "Neon-Raw-Text-Output": "true",
      "Neon-Array-Mode": "true",
    },
    body: JSON.stringify({ query, params: params.map(prepareParam) }),
  });

  if (!res.ok) {
    let detail = "";
    try {
      const j = await res.json();
      detail = j.message || JSON.stringify(j);
    } catch {
      detail = await res.text().catch(() => "");
    }
    throw new Error(`Neon HTTP ${res.status}: ${detail}`);
  }

  const data = await res.json();
  const fieldNames = (data.fields || []).map((f) => f.name);
  const rows = (data.rows || []).map((arr) => {
    const obj = {};
    for (let i = 0; i < fieldNames.length; i++) {
      obj[fieldNames[i]] = arr[i] === undefined ? null : arr[i];
    }
    return obj;
  });

  return { rows, rowCount: data.rowCount ?? rows.length };
}

async function pgFetchOne(connectionString, query, params = []) {
  const { rows } = await pgQuery(connectionString, query, params);
  return rows[0] ?? null;
}

async function pgExecute(connectionString, query, params = []) {
  const { rowCount } = await pgQuery(connectionString, query, params);
  return rowCount;
}

module.exports = { pgQuery, pgFetchOne, pgExecute };
